const input = $input.first().json;
const body = input.body ?? input;

const sessionId = (body.sessionId || '').toString().trim();
const rawMessage = (body.message || '').toString().trim();

const errors = [];
if (!sessionId) errors.push('sessionId es obligatorio.');
if (!rawMessage) errors.push('message no puede estar vacío.');
if (rawMessage.length > 4000) errors.push('message supera el máximo de 4000 caracteres.');

let rateLimited = false;
const data = $getWorkflowStaticData('global');
if (!data.rateLimit) data.rateLimit = {};

if (errors.length === 0) {
  const WINDOW_MS = 60000;
  const MAX_REQUESTS = 10;
  const now = Date.now();
  const bucket = (data.rateLimit[sessionId] || []).filter((t) => now - t < WINDOW_MS);

  if (bucket.length >= MAX_REQUESTS) {
    rateLimited = true;
    errors.push('Has enviado demasiados mensajes. Espera un minuto antes de volver a intentar.');
  } else {
    bucket.push(now);
    data.rateLimit[sessionId] = bucket;
  }
}

return [{
  json: {
    isValid: errors.length === 0,
    rateLimited,
    errorMessage: errors.join(' '),
    sessionId,
    message: rawMessage,
  },
}];

const { sessionId, message } = $json;
const MAX_TURNS = 20;

const data = $getWorkflowStaticData('global');
if (!data.conversations) data.conversations = {};
if (!data.conversations[sessionId]) data.conversations[sessionId] = [];

const history = data.conversations[sessionId].slice(-MAX_TURNS);

const contents = history.map((turn) => ({
  role: turn.role,
  parts: [{ text: turn.text }],
}));

contents.push({ role: 'user', parts: [{ text: message }] });

return [{
  json: {
    sessionId,
    message,
    contents,
  },
}];

const sessionId = $('Code - Construir historial').item.json.sessionId;
const message = $('Code - Construir historial').item.json.message;
const response = $input.first().json;

const reply = response?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('')
  ?? 'No se obtuvo una respuesta del modelo. Intenta reformular tu pregunta.';

const data = $getWorkflowStaticData('global');
const history = data.conversations[sessionId];
history.push({ role: 'user', text: message });
history.push({ role: 'model', text: reply });

const MAX_STORED_TURNS = 40;
if (history.length > MAX_STORED_TURNS) {
  history.splice(0, history.length - MAX_STORED_TURNS);
}

return [{
  json: {
    success: true,
    sessionId,
    reply,
    timestamp: new Date().toISOString(),
  },
}];

const sessionId = $('Code - Construir historial').item.json.sessionId;

return [{
  json: {
    success: false,
    sessionId,
    error: 'No se pudo generar una respuesta en este momento. Intenta de nuevo en unos segundos.',
    code: 'PROVIDER_ERROR',
  },
}];

const code = $json.rateLimited ? 'RATE_LIMITED' : 'VALIDATION_ERROR';

return [{
  json: {
    success: false,
    error: $json.errorMessage,
    code,
  },
}];
